def longestConsecutive(nums):
    if not nums: return 0
    nums = sorted(list(set(nums)))
    longest = cur = 1
    for i in range(1, len(nums)):
        if nums[i] == nums[i-1] + 1:
            cur += 1
            longest = max(longest, cur)
        else:
            cur = 1
    return longest

